import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Showing a sheet's audit lines, optionally only those about one person. */
@RestController
@RequestMapping("/api/audit")
public class AuditViewController {

    public record AuditViewRequest(@NotBlank @Size(max = 100) String sheet, @Size(max = 100) String name) {
    }

    public record AuditViewResponse(List<String> lines) {
    }

    private final AuditViewService service;

    public AuditViewController(AuditViewService service) {
        this.service = service;
    }

    @PostMapping("/list")
    public AuditViewResponse list(@Valid @RequestBody AuditViewRequest req) {
        return new AuditViewResponse(service.lines(req.sheet().trim(), req.name()));
    }
}
package net.officefloor.hq.app.audit;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * Reads a sheet's records back from the audit file, newest first, exactly as the file holds them.
 * It is a view of the file, not a second record: nothing is kept or written here.
 */
@Service
public class AuditViewService {

    /** What may follow a field's value: the line's end, or the next {@code key=} field. */
    private static final Pattern NEXT_FIELD = Pattern.compile("^( [A-Za-z][A-Za-z0-9-]*=.*)?$");

    private final Audit audit;
    private final PersonRepository people;
    private final SheetRepository sheets;

    public AuditViewService(Audit audit, PersonRepository people, SheetRepository sheets) {
        this.audit = audit;
        this.people = people;
        this.sheets = sheets;
    }

    /**
     * The sheet's records, newest first; with a name (blank for none), only those carrying
     * {@code name=<name>} or {@code person=<name>}, the name compared ignoring case and surrounding
     * spaces. With a name, the lines about them on the sheet's descendants (its children, their
     * children, and so on) follow, each sheet's newest first, the sheets in order of id. When the
     * name is a person transferred in, the lines about them from the sheet they came from follow
     * last, newest first, as that sheet's lines are.
     */
    public List<String> lines(String sheet, String name) {
        String person = name == null ? "" : name.trim().toLowerCase(Locale.ROOT);
        List<String> all = audit.lines();
        List<String> found = linesOf(all, sheet, person);
        if (!person.isEmpty()) {
            for (String descendant : descendants(sheet)) {
                found.addAll(linesOf(all, descendant, person));
            }
            people.findBySheetIdAndNameIgnoreCase(sheet, name.trim()).map(Person::getOriginSheet)
                    .ifPresent(origin -> found.addAll(linesOf(all, origin, person)));
        }
        return found;
    }

    /** The ids of the sheet's descendants, at every level, in order of id; the sheet itself never. */
    private List<String> descendants(String sheet) {
        Set<String> seen = new LinkedHashSet<>();
        List<String> todo = new ArrayList<>(List.of(sheet));
        while (!todo.isEmpty()) {
            String at = todo.remove(todo.size() - 1);
            for (Sheet child : sheets.findByParentIdOrderByIdAsc(at)) {
                if (!child.getId().equals(sheet) && seen.add(child.getId())) {
                    todo.add(child.getId());
                }
            }
        }
        List<String> ids = new ArrayList<>(seen);
        Collections.sort(ids);
        return ids;
    }

    /** The sheet's lines, newest first, only those about the (lower-cased) person when one is given. */
    private static List<String> linesOf(List<String> all, String sheet, String person) {
        List<String> found = new ArrayList<>();
        for (String line : all) {
            if (ofSheet(line, sheet) && (person.isEmpty() || about(line, person))) {
                found.add(line);
            }
        }
        Collections.reverse(found);
        return found;
    }

    private static boolean ofSheet(String line, String sheet) {
        String[] fields = line.split(" ", 3);
        return fields.length > 1 && fields[1].equals("sheet=" + sheet);
    }

    /** Whether the line carries name= or person= with this (lower-cased) name as its whole value. */
    private static boolean about(String line, String person) {
        String lower = line.toLowerCase(Locale.ROOT);
        return carries(line, lower, " name=" + person) || carries(line, lower, " person=" + person);
    }

    private static boolean carries(String line, String lower, String field) {
        for (int at = lower.indexOf(field); at >= 0; at = lower.indexOf(field, at + 1)) {
            if (NEXT_FIELD.matcher(line.substring(at + field.length())).matches()) {
                return true;
            }
        }
        return false;
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

// The audit viewer: the sheet's audit lines exactly as the audit file holds them, newest first.
// With a name in the filter, only the lines about that person (name= or person= that name,
// compared ignoring case and surrounding spaces), then those on the sheet's descendants and on the
// sheet the person came from. It reads the file; it records nothing itself.
@Component({
  selector: 'app-audit-view',
  template: `
    <section aria-labelledby="audit-heading">
      <h2 id="audit-heading">Audit</h2>
      <form aria-label="Audit filter" (submit)="show($event)">
        <label for="audit-filter">Person</label>
        <input
          id="audit-filter"
          data-testid="audit-filter"
          [value]="filterInput()"
          (input)="filterInput.set($any($event.target).value); error.set(null)"
        />
        <button type="submit" data-testid="audit-show">Show</button>
        @if (error(); as err) {
          <p role="alert" data-testid="audit-error">{{ err }}</p>
        }
      </form>
      <ol data-testid="audit-lines" aria-label="Audit lines">
        @for (line of lines(); track $index) {
          <li data-testid="audit-line">{{ line }}</li>
        }
      </ol>
    </section>
  `,
})
export class AuditView {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  protected readonly filterInput = signal('');
  protected readonly lines = signal<string[]>([]);
  protected readonly error = signal<string | null>(null);
  /** Counts presses of show, so only the answer to the latest one is shown. */
  private shown = 0;

  constructor() {
    // A (re-)loaded sheet starts with nothing shown.
    effect(() => {
      this.session.sheet();
      this.session.loads();
      this.shown++;
      this.lines.set([]);
      this.error.set(null);
    });
  }

  protected async show(event: Event): Promise<void> {
    event.preventDefault();
    const press = ++this.shown;
    this.lines.set([]);
    this.error.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    try {
      const res = await firstValueFrom(
        this.http.post<{ lines: string[] }>('/api/audit/list', { sheet, name: this.filterInput() }),
      );
      if (press === this.shown) this.lines.set(res.lines);
    } catch {
      if (press === this.shown) this.error.set('Could not read the audit lines.');
    }
  }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.role.RoleService;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The records that only report figures: never marked as made for a delegating steward. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;
    // looked up when used: the role service records its own changes here
    private final ObjectProvider<RoleService> roles;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<RoleService> roles) {
        this.file = Path.of(path);
        this.roles = roles;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing. Outside a transaction the record is appended at once.
     */
    public void recordOnCommit(String change) {
        String entry = change + delegated(change);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /**
     * The ending of a change's record made by a user acting as a steward under a delegation in force
     * on the sheet's today: {@code for=<the steward who delegated>}; otherwise nothing.
     */
    private String delegated(String entry) {
        String[] fields = entry.split(" ");
        if (FIGURES.contains(fields[0])) {
            return "";
        }
        String sheet = field(fields, "sheet=");
        String by = field(fields, "by=");
        if (sheet == null || by == null) {
            return "";
        }
        return roles.getObject().delegatorOf(sheet, by).map(steward -> " for=" + steward).orElse("");
    }

    private static String field(String[] fields, String name) {
        for (String f : fields) {
            if (f.startsWith(name)) {
                return f.substring(name.length());
